import{_ as t,o as a,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"State of the Cephalopod 2022","description":"","frontmatter":{"title":"State of the Cephalopod 2022","date":"2022-11-09T00:00:00.000Z","updated":"2022-11-10T00:00:00.000Z","tags":["Ceph","分布式存储","Quincy版本","Reef版本","Ceph基金会"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/State_of_the_Cephalopod_2022.md","filePath":"posts/2022/State_of_the_Cephalopod_2022.md","lastUpdated":1780459816000}'),r={name:"posts/2022/State_of_the_Cephalopod_2022.md"};function i(n,e,s,h,d,p){return a(),o("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议主要更新了Ceph项目的最新进展，包括技术层面和项目管理层面。会议重点讨论了Quincy和Reef版本的更新内容。</p><h4 id="项目管理更新" tabindex="-1">项目管理更新 <a class="header-anchor" href="#项目管理更新" aria-label="Permalink to &quot;项目管理更新&quot;">​</a></h4><ul><li><strong>领导结构变更</strong>：Ceph项目创始人Sage Weil逐渐退出日常管理，项目采用新的治理模式，由Ceph领导团队和选举产生的执行委员会共同领导。</li><li><strong>开放性和协作</strong>：Ceph领导团队会议对所有人开放，会议笔记通过邮件列表共享，技术讨论和项目影响决策也在此进行。</li><li><strong>重点领域</strong>：过去几年重点改善了内部发布流程，增强了稳定性，引入了发布候选版本，加强了性能和可扩展性测试。</li></ul><h4 id="技术更新" tabindex="-1">技术更新 <a class="header-anchor" href="#技术更新" aria-label="Permalink to &quot;技术更新&quot;">​</a></h4><ul><li><strong>性能与可扩展性</strong>：Quincy版本在大型测试集群中进行了大量测试，包括在澳大利亚的Pawsey超级计算中心测试了4000个OSD，以及在逻辑规模上模拟大型集群测试。</li><li><strong>关键功能更新</strong>： <ul><li><strong>RADOS</strong>：Quincy版本中引入了默认启用的QoS功能，改进了Blue Store的性能，包括移除RocksDB的分配元数据，改进了BlueFS，实现了更细粒度的锁定机制。</li><li><strong>Reef版本展望</strong>：将引入客户端间QoS的初步实现，改进M clock调度器以支持高优先级操作，Blue Store将支持自定义WAL，改进4K分配单元等。</li><li><strong>Crimson项目</strong>：作为高性能的RADOS读取器，Crimson在Reef版本中将增加多反应器支持，改进可用性，并计划在S版本中完成scrub实现。</li><li><strong>Telemetry</strong>：Quincy版本增强了数据收集流程，新增了Both Channel收集性能指标，改进了崩溃报告分析，Reef版本将继续优化数据分析和设备故障预测模型。</li></ul></li></ul><h4 id="社区和基金会动态" tabindex="-1">社区和基金会动态 <a class="header-anchor" href="#社区和基金会动态" aria-label="Permalink to &quot;社区和基金会动态&quot;">​</a></h4><ul><li><strong>Ceph基金会</strong>：维护了健康的会员结构，包括10个主要成员，13个普通成员和11个关联成员，负责协调活动和资助上游测试实验室。</li><li><strong>用户和开发者活动</strong>：推出了每月虚拟事件，鼓励新开发者参与，如Google Summer of Code和Outreachy，以及定期的技术讲座。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>版本更新</strong>：当前专注于Reef版本的开发，即将开始S版本的命名讨论和开发。</li><li><strong>社区参与</strong>：鼓励社区成员参与技术讨论和测试新功能，特别是对Telemetry的参与和反馈。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议强调了Ceph项目在技术和管理层面上的持续进步，呼吁社区成员积极参与和支持即将到来的版本更新和技术发展。会议资料将通过邮件列表分享，欢迎后续交流和讨论。</p><p>[改进后的总结中保留了计算机科学/ceph相关领域的英文原文关键词，如Ceph、Quincy版本、Reef版本、RADOS、Blue Store、BlueFS、Crimson项目、Telemetry等，确保了总结的准确性和专业性。]</p>',14)])])}const _=t(r,[["render",i]]);export{c as __pageData,_ as default};
